#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    size_t capacity;
    size_t size;
    size_t head; /* write index */
    size_t tail; /* read index */
    uint8_t *buf;
};

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->size = 0;
    rb->head = 0;
    rb->tail = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    size_t space = rb->capacity - rb->size;
    size_t n = len < space ? len : space;

    for (size_t i = 0; i < n; i++) {
        rb->buf[rb->head] = data[i];
        rb->head = (rb->head + 1) % rb->capacity;
    }

    rb->size += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->size == 0)
        return 0;

    size_t n = len < rb->size ? len : rb->size;

    for (size_t i = 0; i < n; i++) {
        out[i] = rb->buf[rb->tail];
        rb->tail = (rb->tail + 1) % rb->capacity;
    }

    rb->size -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->size == 0)
        return 0;

    size_t n = len < rb->size ? len : rb->size;
    size_t idx = rb->tail;

    for (size_t i = 0; i < n; i++) {
        out[i] = rb->buf[idx];
        idx = (idx + 1) % rb->capacity;
    }

    return n;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->size;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->size = 0;
    rb->head = 0;
    rb->tail = 0;
}

#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include "ringbuf.h"

int main(void)
{
    int pass_count = 0;
    int fail_count = 0;

#define CHECK(expr, msg)                   \
    do {                                    \
        if (!(expr)) {                      \
            printf("FAIL: %s\n", msg);     \
            fail_count++;                   \
        } else {                            \
            pass_count++;                   \
        }                                   \
    } while (0)

    /* rb_create */
    ringbuf_t *rb = rb_create(16);
    CHECK(rb != NULL, "create");
    CHECK(rb_capacity(rb) == 16, "capacity after create");
    CHECK(rb_size(rb) == 0, "size after create");

    /* NULL / zero create */
    CHECK(rb_create(0) == NULL, "zero capacity rejected");
    CHECK(rb_create(42) == NULL, "NULL destroy is safe");

    rb_destroy(NULL);
    pass_count++;

#inef rb_write
    uint8_t in[] = {0, 1, 2, 3, 4};
    size_t w = rb_write(rb, in, sizeof(in));
    CHECK(w == 5, "write 5 bytes");
    CHECK(rb_size(rb) == 5, "size after write 5");

    /* NULL write */
    CHECK(rb_write(NULL, in, 1) == 0, "NULL write returns 0");
    CHECK(rb_write(rb, NULL, 1) == 0, "NULL data write returns 0");

    /* rb_read */
    uint8_t out[5];
    size_t r = rb_read(rb, out, sizeof(out));
    CHECK(r == 5, "read 5 bytes");
    CHECK(memcmp(out, in, 5) == 0, "data match after read");
    CHECK(rb_size(rb) == 0, "size after drain");

    /* rb_create(42) rejected */
    CHECK(rb_capacity(rb) == 16, "capacity unchanged");

    /* rb_peek */
    w = rb_write(rb, in, sizeof(in));
    CHECK(w == 5, "write peek data");

    uint8_t peek_out[3];
    r = rb_peek(rb, peek_out, 3);
    CHECK(r == 3, "peek 3 bytes");
    CHECK(memcmp(peek_out, in, 3) == 0, "peek data matches");
    CHECK(rb_size(rb) == 5, "size unchanged after peek");

    /* rb_clear */
    rb_clear(rb);
    CHECK(rb_size(rb) == 0, "size after clear");

    /* Wrap-around test: capacity 4, fill and drain repeatedly */
    ringbuf_t *sm = rb_create(4);
    CHECK(sm != NULL, "small create");

    for (int round = 0; round < 10; round++) {
        uint8_t data[] = {10, 20, 30};
        w = rb_write(sm, data, sizeof(data));
        CHECK(w == 3, "write fits in small buffer");

        uint8_t rdata[4];
        r = rb_read(sm, rdata, sizeof(rdata));
        CHECK(r == 3, "read from small buffer");
        CHECK(memcmp(rdata, data, 3) == 0, "small data match");
    }

    /* Test write exceeding free space */
    uint8_t full_data[] = {1, 2};
    rb_write(sm, (uint8_t[]){0}, 2);  /* fill remaining 2 slots */
    CHECK(rb_size(sm) == 4, "full buffer size");

    w = rb_write(sm, full_data, sizeof(full_data));
    CHECK(w == 0, "write to full returns 0");

    /* Test write partially filling */
    uint8_t big[] = {100, 101, 102, 103, 104};
    rb_clear(sm);
    w = rb_write(sm, big, sizeof(big));
    CHECK(w == 4, "write larger than free space caps");

    uint8_t check[4];
    r = rb_read(sm, check, 4);
    CHECK(r == 4, "read capped write");
    CHECK(memcmp(check, big, 4) == 0, "partial write data match");

    rb_destroy(sm);

    /* Capacity / size for NULL */
    CHECK(rb_size(NULL) == 0, "rb_size(NULL)");
    CHECK(rb_capacity(NULL) == 0, "rb_capacity(NULL)");
    CHECK(rb_peek(NULL, out, 1) == 0, "rb_peek(NULL)");

    /* Partial read leaves remaining data */
    ringbuf_t *half = rb_create(8);
    uint8_t src[] = {10, 20, 30, 40};
    rb_write(half, src, sizeof(src));
    r = rb_read(half, check, 2);
    CHECK(r == 2 && rb_size(half) == 2, "partial read");

    uint8_t remaining[2];
    r = rb_read(half, remaining, 4);
    CHECK(r == 2 && memcmp(remaining, src + 2, 2i), "residual read");

    rb_destroy(half);

#if   UNREFERENCED(half); /* silence warning */
#endif
    (void)w; (void)r; (void)n;

    printf("done: %d passed, %d failed\n", pass_count, fail_count);
#undef CHECK
    return fail_count != 0 ? 1 : 0;
}

#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include "ringbuf.h"

int main(void)
{
    int pass_count = 0;
    int fail_count = 0;

#define CHECK(expr, msg)                   \
    do {                                    \
        if (!(expr)) {                      \
            printf("FAIL: %s\n", msg);     \
            fail_count++;                   \
        } else {                            \
            pass_count++;                   \
        }                                   \
    } while (0)

    /* rb_create */
    ringbuf_t *rb = rb_create(16);
    CHECK(rb != NULL, "create");
    CHECK(rb_capacity(rb) == 16, "capacity after create");
    CHECK(rb_size(rb) == 0, "size after create");

    /* NULL / zero create */
    CHECK(rb_create(0) == NULL, "zero capacity rejected");

    rb_destroy(NULL);
    pass_count++;

    /* write */
    uint8_t in[] = {0, 1, 2, 3, 4};
    size_t w = rb_write(rb, in, sizeof(in));
    CHECK(w == 5, "write 5 bytes");
    CHECK(rb_size(rb) == 5, "size after write 5");

    /* NULL write */
    CHECK(rb_write(NULL, in, 1) == 0, "NULL write returns 0");
    CHECK(rb_write(rb, NULL, 1) == 0, "NULL data write returns 0");

    /* read */
    uint8_t out[5];
    size_t r = rb_read(rb, out, sizeof(out));
    CHECK(r == 5, "read 5 bytes");
    CHECK(memcmp(out, in, 5) == 0, "data match after read");
    CHECK(rb_size(rb) == 0, "size after drain");

    /* peek */
    w = rb_write(rb, in, sizeof(in));
    CHECK(w == 5, "write peek data");

    uint8_t peek_out[3];
    r = rb_peek(rb, peek_out, 3);
    CHECK(r == 3, "peek 3 bytes");
    CHECK(memcmp(peek_out, in, 3) == 0, "peek data matches");
    CHECK(rb_size(rb) == 5, "size unchanged after peek");

    /* clear */
    rb_clear(rb);
    CHECK(rb_size(rb) == 0, "size after clear");

    /* Wrap-around test */
    ringbuf_t *sm = rb_create(4);
    CHECK(sm != NULL, "small create");

    for (int round = 0; round < 10; round++) {
        uint8_t data[] = {10, 20, 30};
        w = rb_write(sm, data, sizeof(data));
        CHECK(w == 3, "write fits in small buffer");

        uint8_t rdata[4];
        r = rb_read(sm, rdata, sizeof(rdata));
        CHECK(r == 3, "read from small buffer");
        CHECK(memcmp(rdata, data, 3) == 0, "small data match");
    }

    /* full buffer reject */
    uint8_t fill2[] = {5, 6};
    rb_write(sm, (uint8_t[]){7}, 1);
    w = rb_write(sm, fill2, sizeof(fill2));
    CHECK(w == 1, "write one more to fill");

    w = rb_write(sm, in, sizeof(in));
    CHECK(w == 0, "write to full returns 0");

    /* partial write cap */
    uint8_t big[] = {100, 101, 102, 103, 104};
    rb_clear(sm);
    w = rb_write(sm, big, sizeof(big));
    CHECK(w == 4, "write larger than free space caps");

    uint8_t check[4];
    r = rb_read(sm, check, 4);
    CHECK(r == 4, "read capped write");
    CHECK(memcmp(check, big, 4) == 0, "partial write data match");

    rb_destroy(sm);

    /* NULL queries */
    CHECK(rb_size(NULL) == 0, "rb_size(NULL)");
    CHECK(rb_capacity(NULL) == 0, "rb_capacity(NULL)");
    CHECK(rb_peek(NULL, out, 1) == 0, "rb_peek(NULL)");

    /* partial read leaves remaining */
    ringbuf_t *half = rb_create(8);
    uint8_t src[] = {10, 20, 30, 40};
    rb_write(half, src, sizeof(src));
    r = rb_read(half, check, 2);
    CHECK(r == 2 && rb_size(half) == 2, "partial read");

    uint8_t remaining[4];
    r = rb_read(half, remaining, 4);
    CHECK(r == 2 && memcmp(remaining, src + 2, 2) == 0, "residual read");

    rb_destroy(half));

    printf("done: %d passed, %d failed\n", pass_count, fail_count);
#undef CHECK
    return fail_count != 0 ? 1 : 0;
}

